# -*- coding: utf-8 -*-
"""Рядок 153 (3): обгортка над `namir_zhyva_88.py` — та сама батарея (12 текстів наміру + 4 K-IO-02), той самий промпт і розбір
паспорта, лише ІНША МОДЕЛЬ LM Studio; друкує с/текст і VRAM. Сам файл рядка 88 не міняється: обгортка виконує його текст, у якому
назва моделі підмінена. Яку назву підміняти, обгортка ЧИТАЄ з `model="…"` рядка 88, а не знає літералом, і без аргументу міряє саме те, що там стоїть: дослівний літерал робив зміну типової моделі поломкою обгортки (виміряно 24.09 — саме це й сталося, коли типовою стала gemma). Модель, якої LM Studio не бачить, обгортка називає по імені, а не падає на 404. `--сам`: замість LM Studio відповідає очікування самого тексту (мусить вийти «намір: 12/12 · K-IO-02 … 4/4» — перевірка підрахунку обгортки).
ТЕМПЕРАТУРА 0 ТУТ ТИПОВА (`--як_є` вимикає). Рядок 88 температури не шле зовсім, тобто модель СЕМПЛЮЄ, і 24.09 п'ять прогонів тієї
самої моделі на тій самій батареї дали намір 9,10,9,9,9/12 і K-IO-02 4,4,4,3,4 — різниця в одиницю тут шум, а не модель. З `--t0`
три прогони дали 9/12 · 4/4 без відхилень. ТОЧКА ВІДЛІКУ 24.09: qwen3-vl-8b-instruct — намір 9/12 · K-IO-02 4/4 · 7.3 с/текст;
КАНДИДАТ gemma-4-12b-it-qat — намір 11/12 · K-IO-02 4/4 · 8.3 с/текст (+12 %), і саме вона тепер типова в рядку 88 (чому — там у докстрінгу). Абзац нижче описує qwen, бо на ній ці хиби й знайдені; у gemma з трьох лишилася сама (а), і то на одному тексті. Ще двоє, що їх лічильник теж не бачить: qwen вигадала макіяж на текстах 4, 6 і 10 та прикраси на 6 (про них там ні слова) — разом із (б) це ШІСТЬ вигадок проти НУЛЯ в gemma; і пораду, теми якої дав код, qwen дала лише на тексті 6 (списану), а на 12, 13, 14 змовчала — тобто м'яке запрошення, яке власник просив 20.09, до жінки просто не доходило. Хиба самої gemma привела до ПРАВКИ ПРОМПТА, тож УВАГА НА ПРОМПТ, НА ЯКОМУ МІРЯНО: на текстах 12 і 13 вона зверталась на «ви», хоч приклад форми в промпті — на «ти»; форму промпт не ЗАДАВАВ, лише ПОКАЗУВАВ, і це була діра промпта, не моделі. 24.09 форму названо словами (`паспорт_нагоди.промпт_паспорта`, поле «відповідь_людині»), і на НОВОМУ промпті gemma дає порад із «ви» 0 з 4 проти 2 з 4, а намір 12/12 — двома прогонами поспіль, дослівно однаковими. Числа 9/12 і 11/12 вище — на СТАРОМУ промпті, і саме вони рівні між собою; КОНТРОЛЬНИЙ ПРОГІН ЗРОБЛЕНО, і він лишає gemma типовою: qwen на НОВОМУ промпті — намір 9/12, тобто правка її НЕ підіймає (gemma на тому самому промпті 12/12), а K-IO-02 у неї впав 4/4 → 3/4, бо на тексті 13 вона вигадала прикраси «золото», яких у тексті нема. Одиниця — шум за правилом вище, але ВИГАДКА, а їх я рахую окремо від лічильника: у gemma їх нуль на обох промптах. ТРЕТІЙ КАНДИДАТ, Qwen3.5-9B Q8_0 без думання: намір 10/12 · K-IO-02 2/4 · 11.0 с/текст — програє gemma на всіх трьох.
ЩО ВИДНО В ТАБЛИЦІ, А ЛІЧИЛЬНИК НЕ РАХУЄ (24.09, читала очима). (а) Усі три промахи наміру — це тексти 1–3, тобто ВСІ нейтральні:
де жінка сказала лише нагоду, модель дає context_optimal/comfort_first замість conventional, хоча промпт прямо каже «нагода,
місце чи дрес-код наміру НЕ дають». (б) На текстах 1 і 2 вона вигадує мету «лестити», хоч про мету там ні слова — це K-IO-02,
але лічильник K-IO-02 дивиться лише тексти 13–16. (в) Коли код пропонує теми поради (текст 6), модель СПИСУЄ приклад із промпта,
хоч там сказано «своїми словами, не цими», ще й із повтором («чи хочеш сьогодні бути помітною» двічі). Кандидата дивитись на це саме.
`cd джерела && python проби/vymir_namiru_153.py <модель>`"""
import io, json, os, re, subprocess, sys, time, urllib.request
ШЛЯХ = os.path.join(os.path.dirname(os.path.abspath(__file__)), "namir_zhyva_88.py")
текст = open(ШЛЯХ, encoding="utf-8").read()
ТИПОВА = re.findall(r'model="([^"]+)"', текст)   # не дослівний літерал: інакше зміна типової моделі ламає обгортку (пастка рядка 153)
if len(ТИПОВА) != 1: sys.exit("у namir_zhyva_88.py не одна назва моделі (%d) — обгортка не знає, що підміняти" % len(ТИПОВА))
мод, сам = next((a for a in sys.argv[1:] if not a.startswith("--")), ТИПОВА[0]), "--сам" in sys.argv
if not {"--t0", "--як_є"} & set(sys.argv): sys.argv.append("--t0")   # порівняння моделей має сенс лише без семплювання (див. докстрінг)
простір = {"__name__": "__main__", "__file__": ШЛЯХ}
def відповідь_очікуванням(запит, timeout=None):
    """Підміна `urlopen` для `--сам`: відповідь у форматі LM Studio, де JSON паспорта — рівно очікування тексту з ТЕКСТИ рядка 88."""
    оч = next(о for с, о in простір["ТЕКСТИ"] if с in json.loads(запит.data)["messages"][0]["content"])
    від = {"намір": оч} if isinstance(оч, str) else {"мета": оч[0], "макіяж": оч[1] and {"рівень": оч[1]}, "прикраси": оч[2]}
    return io.BytesIO(json.dumps({"choices": [{"message": {"content": json.dumps(від, ensure_ascii=False)}}]}).encode("utf-8"))
if сам: urllib.request.urlopen = відповідь_очікуванням
else:
    try: є = {m["id"] for m in json.load(urllib.request.urlopen("http://127.0.0.1:1234/v1/models", timeout=10))["data"]}
    except Exception as e: sys.exit("LM Studio не відповідає (%s) — модель «%s» не виміряти" % (type(e).__name__, мод))
    мод in є or sys.exit("LM Studio не знає моделі «%s» — назви, які вона бачить: %s" % (мод, ", ".join(sorted(є))))   # назвати брак, а не впасти на 404
т0 = time.time()
exec(compile(текст.replace('"%s"' % ТИПОВА[0], json.dumps(мод)), ШЛЯХ, "exec"), простір)
try: vram = subprocess.run(["nvidia-smi", "--query-gpu=memory.used,memory.total", "--format=csv,noheader"], capture_output=True, text=True, timeout=20).stdout.strip()
except Exception as e: vram = "nvidia-smi: " + type(e).__name__
print("(3) модель %s%s · %.1f с/текст (%d текстів) · VRAM %s" % (мод, " --сам (очікування замість моделі)" if сам else "", (time.time() - т0) / len(простір["ТЕКСТИ"]), len(простір["ТЕКСТИ"]), vram))
sys.exit(1 if сам and (простір["влучень"], простір["чисто"]) != (12, 4) else 0)
